code.code:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/results.csv"
  },
  "transform": [
    {
      "aggregate": [
        {"op": "mean", "field": "home_score", "as": "mean_home_score"},
        {"op": "mean", "field": "away_score", "as": "mean_away_score"}
      ],
      "groupby": []
    },
    {
      "fold": ["mean_home_score", "mean_away_score"],
      "as": ["score_type", "average_score"]
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "score_type",
      "type": "nominal",
      "title": "Score Type"
    },
    "y": {
      "field": "average_score",
      "type": "quantitative",
      "title": "Average Score"
    },
    "color": {
      "field": "score_type",
      "type": "nominal",
      "title": "Score Type"
    }
  },
  "title": "Comparison of Home and Away Scores (Average)"
}

